Archivo: {{$json.original_filename}}
Ruta: {{$json.file_path}}

parameters.functionCode:
// Parsea la respuesta JSON de GPT-4 y la combina con el contexto tenant
const ctx = $('Extraer Contexto Tenant').item.json;
const gptResponse = $input.item.json.message?.content || $input.item.json.text || '';

try {
  let jsonStr = gptResponse;
  const m = gptResponse.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (m) jsonStr = m[1].trim();
  const datos = JSON.parse(jsonStr);

  return { json: {
    ...datos,
    url_factura: ctx.file_url || ctx.file_path || '',
    apiKey: ctx.apiKey,
    empresaId: ctx.empresaId,
    source_filename: ctx.original_filename,
    extraction_success: true
  }};
} catch (error) {
  return { json: {
    error: 'No se pudo parsear la respuesta de GPT-4: ' + error.message,
    raw_response: gptResponse.slice(0, 1000),
    extraction_success: false,
    apiKey: ctx.apiKey,
    empresaId: ctx.empresaId
  }};
}
